\set ON_ERROR_STOP on
CREATE SCHEMA plugin_demo;
CREATE TABLE plugin_demo.notes (id text COLLATE pg_catalog."C" PRIMARY KEY, owner text COLLATE pg_catalog."C" NOT NULL);
INSERT INTO plugin_demo.notes VALUES ('a','A'),('b','B'),('c','C'),('d','D');
SELECT cn.nspname, co.collname, co.collisdeterministic FROM pg_catalog.pg_attribute AS a JOIN pg_catalog.pg_class AS c ON c.oid = a.attrelid JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace JOIN pg_catalog.pg_collation AS co ON co.oid = a.attcollation JOIN pg_catalog.pg_namespace AS cn ON cn.oid = co.collnamespace WHERE n.nspname = 'plugin_demo'::pg_catalog.text AND c.relname = 'notes'::pg_catalog.text AND a.attname = 'id'::pg_catalog.text AND a.attnum > 0 AND NOT a.attisdropped;
WITH "__weft_source" AS MATERIALIZED (SELECT ROW_NUMBER() OVER (ORDER BY "r"."id" COLLATE pg_catalog."C" ASC) AS "__weft_ordinal", "r"."id" COLLATE pg_catalog."C" AS "__weft_page_key", "r"."owner" COLLATE pg_catalog."C" AS "__weft_field_1" FROM "plugin_demo"."notes" AS "r" WHERE (TRUE) AND (NULL::pg_catalog.text IS NULL OR "r"."id" COLLATE pg_catalog."C" > NULL::pg_catalog.text COLLATE pg_catalog."C") ORDER BY "r"."id" COLLATE pg_catalog."C" ASC LIMIT (2::pg_catalog.int8 + 1)), "__weft_guard" AS MATERIALIZED (SELECT CASE WHEN COALESCE(pg_catalog.sum(pg_catalog.octet_length(pg_catalog.convert_to(pg_catalog.row_to_json(f)::pg_catalog.text, 'UTF8'))),0) <= 8388608 THEN 1::pg_catalog.int8 ELSE 1::pg_catalog.int8 / (pg_catalog.count(*) - pg_catalog.count(*)) END AS ok FROM "__weft_source" AS f) SELECT f.* FROM "__weft_source" AS f ORDER BY f."__weft_ordinal" LIMIT ALL OFFSET (SELECT 1 - ok FROM "__weft_guard");
WITH "__weft_source" AS MATERIALIZED (SELECT ROW_NUMBER() OVER (ORDER BY "r"."id" COLLATE pg_catalog."C" ASC) AS "__weft_ordinal", "r"."id" COLLATE pg_catalog."C" AS "__weft_page_key", "r"."owner" COLLATE pg_catalog."C" AS "__weft_field_1" FROM "plugin_demo"."notes" AS "r" WHERE (TRUE) AND ('b'::pg_catalog.text IS NULL OR "r"."id" COLLATE pg_catalog."C" > 'b'::pg_catalog.text COLLATE pg_catalog."C") ORDER BY "r"."id" COLLATE pg_catalog."C" ASC LIMIT (2::pg_catalog.int8 + 1)), "__weft_guard" AS MATERIALIZED (SELECT CASE WHEN COALESCE(pg_catalog.sum(pg_catalog.octet_length(pg_catalog.convert_to(pg_catalog.row_to_json(f)::pg_catalog.text, 'UTF8'))),0) <= 8388608 THEN 1::pg_catalog.int8 ELSE 1::pg_catalog.int8 / (pg_catalog.count(*) - pg_catalog.count(*)) END AS ok FROM "__weft_source" AS f) SELECT f.* FROM "__weft_source" AS f ORDER BY f."__weft_ordinal" LIMIT ALL OFFSET (SELECT 1 - ok FROM "__weft_guard");
WITH "__weft_source" AS MATERIALIZED (SELECT ROW_NUMBER() OVER (ORDER BY "r"."id" COLLATE pg_catalog."C" ASC) AS "__weft_ordinal", "r"."id" COLLATE pg_catalog."C" AS "__weft_page_key" FROM "plugin_demo"."notes" AS "r" WHERE (TRUE) AND (NULL::pg_catalog.text IS NULL OR "r"."id" COLLATE pg_catalog."C" > NULL::pg_catalog.text COLLATE pg_catalog."C") ORDER BY "r"."id" COLLATE pg_catalog."C" ASC LIMIT (2::pg_catalog.int8 + 1)), "__weft_guard" AS MATERIALIZED (SELECT CASE WHEN COALESCE(pg_catalog.sum(pg_catalog.octet_length(pg_catalog.convert_to(pg_catalog.row_to_json(f)::pg_catalog.text, 'UTF8'))),0) <= 8388608 THEN 1::pg_catalog.int8 ELSE 1::pg_catalog.int8 / (pg_catalog.count(*) - pg_catalog.count(*)) END AS ok FROM "__weft_source" AS f) SELECT f.* FROM "__weft_source" AS f ORDER BY f."__weft_ordinal" LIMIT ALL OFFSET (SELECT 1 - ok FROM "__weft_guard");
CREATE TABLE plugin_demo."note%""s" ("key%""id" text COLLATE pg_catalog."C" PRIMARY KEY, owner text COLLATE pg_catalog."C" NOT NULL);
INSERT INTO plugin_demo."note%""s" VALUES ('a','A'),('b','B'),('c','C');
SELECT cn.nspname, co.collname, co.collisdeterministic FROM pg_catalog.pg_attribute AS a JOIN pg_catalog.pg_class AS c ON c.oid = a.attrelid JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace JOIN pg_catalog.pg_collation AS co ON co.oid = a.attcollation JOIN pg_catalog.pg_namespace AS cn ON cn.oid = co.collnamespace WHERE n.nspname = 'plugin_demo'::pg_catalog.text AND c.relname = 'note%"s'::pg_catalog.text AND a.attname = 'key%"id'::pg_catalog.text AND a.attnum > 0 AND NOT a.attisdropped;
WITH "__weft_source" AS MATERIALIZED (SELECT ROW_NUMBER() OVER (ORDER BY "r"."key%""id" COLLATE pg_catalog."C" ASC) AS "__weft_ordinal", "r"."key%""id" COLLATE pg_catalog."C" AS "__weft_page_key", "r"."owner" COLLATE pg_catalog."C" AS "__weft_field_1" FROM "plugin_demo"."note%""s" AS "r" WHERE (TRUE) AND (NULL::pg_catalog.text IS NULL OR "r"."key%""id" COLLATE pg_catalog."C" > NULL::pg_catalog.text COLLATE pg_catalog."C") ORDER BY "r"."key%""id" COLLATE pg_catalog."C" ASC LIMIT (2::pg_catalog.int8 + 1)), "__weft_guard" AS MATERIALIZED (SELECT CASE WHEN COALESCE(pg_catalog.sum(pg_catalog.octet_length(pg_catalog.convert_to(pg_catalog.row_to_json(f)::pg_catalog.text, 'UTF8'))),0) <= 8388608 THEN 1::pg_catalog.int8 ELSE 1::pg_catalog.int8 / (pg_catalog.count(*) - pg_catalog.count(*)) END AS ok FROM "__weft_source" AS f) SELECT f.* FROM "__weft_source" AS f ORDER BY f."__weft_ordinal" LIMIT ALL OFFSET (SELECT 1 - ok FROM "__weft_guard");
